input.command:
mkdir -p /tmp/probe/bin && cat > /tmp/probe/helper.sh <<'EOF'
Z=/workspace/executable
fresh() { export _ZO_DATA_DIR=$(mktemp -d /tmp/probe/zd.XXXXXX); }
dump() { $Z query --list --all --score 2>&1; echo "dump_exit=$?"; }
run() { echo "--- CMD: $* ---"; "$@" > /tmp/probe/.out 2>/tmp/probe/.err; local e=$?; echo "exit=$e"; echo "stdout=[$(cat /tmp/probe/.out)]"; echo "stderr=[$(cat /tmp/probe/.err)]"; }
EOF
echo ok; ls /tmp/probe

toolUseResult:
InputValidationError: [
  {
    "code": "custom",
    "path": [
      "command"
    ],
    "message": "command contains control characters that would be hidden in the approval dialog"
  }
]

input.command:
cd /tmp/pz && . ./h.sh
E='env -u _ZO_DATA_DIR'
echo "### relative _ZO_DATA_DIR"; rm -rf /tmp/pz/dd; mkdir -p /tmp/pz/dd; ( cd /tmp/pz/dd && _ZO_DATA_DIR=reldir _ZO_EXCLUDE_DIRS= $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"; find /tmp/pz/dd -type f -o -type d | sort )
echo "### relative ./x"; ( cd /tmp/pz/dd && _ZO_DATA_DIR=./x/y _ZO_EXCLUDE_DIRS= $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"; find /tmp/pz/dd | sort )
echo "### nonexistent nested absolute"; rm -rf /tmp/pz/deepdd; _ZO_DATA_DIR=/tmp/pz/deepdd/a/b/c _ZO_EXCLUDE_DIRS= $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"; find /tmp/pz/deepdd | sort
echo "### empty _ZO_DATA_DIR"; _ZO_DATA_DIR= _ZO_EXCLUDE_DIRS= $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"
echo "### _ZO_DATA_DIR is a file"; touch /tmp/pz/ddfile; _ZO_DATA_DIR=/tmp/pz/ddfile _ZO_EXCLUDE_DIRS= $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"
echo "### _ZO_DATA_DIR under a file"; _ZO_DATA_DIR=/tmp/pz/ddfile/sub _ZO_EXCLUDE_DIRS= $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"
echo "### _ZO_DATA_DIR with trailing slash"; rm -rf /tmp/pz/dd2; _ZO_DATA_DIR=/tmp/pz/dd2/ _ZO_EXCLUDE_DIRS= $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"; find /tmp/pz/dd2 | sort
echo "### _ZO_DATA_DIR relative with .."; rm -rf /tmp/pz/dd3; mkdir -p /tmp/pz/dd3/x; ( cd /tmp/pz/dd3/x && _ZO_DATA_DIR=../y _ZO_EXCLUDE_DIRS= $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"; find /tmp/pz/dd3 | sort )

cd /tmp/pz && . ./h.sh
echo "### HOME unset: is passwd home (/root) excluded by default?"; mkdir -p /root/zx
fresh; env -u _ZO_EXCLUDE_DIRS -u HOME -u XDG_DATA_HOME _ZO_DATA_DIR=$_ZO_DATA_DIR $Z add /root 2>&1; echo "exit=$?"; raw | grep -c path=
echo "### HOME=/root: excluded?"; fresh; env -u _ZO_EXCLUDE_DIRS HOME=/root _ZO_DATA_DIR=$_ZO_DATA_DIR $Z add /root 2>&1; echo "exit=$?"; ls $_ZO_DATA_DIR
echo "### HOME relative + explicit data dir"; fresh; env -u _ZO_EXCLUDE_DIRS HOME=relhome _ZO_DATA_DIR=$_ZO_DATA_DIR $Z add /tmp/pz/w/a 2>&1; echo "exit=$?"; raw | grep path=
echo "### HOME=/tmp/pz/w  add /tmp/pz/w and /tmp/pz/w/a"; fresh; env -u _ZO_EXCLUDE_DIRS HOME=/tmp/pz/w _ZO_DATA_DIR=$_ZO_DATA_DIR $Z add /tmp/pz/w /tmp/pz/w/a; raw | grep path=
